1	// Shared vocabulary for the sfvictorian build: palette.json ids as constants, plan.md SITE/LEVELS coordinates, and one
2	// helper per plan.md VOCABULARY item. Every helper takes the grid first (g), then the plan's parameters.
3	// Shell and ground helpers (wallCell, wallLine, slab, gardenBed, vegBed, citrusTree's podzol) write their own cells.
4	// Everything else adds into air only: a cell another part already owns is skipped, never overwritten (put()).
5	import { B, DIRS } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
6	
