50	export const DARK_OAK_STAIRS = "dark_oak_stairs";
51	export const DARK_OAK_FENCE = "dark_oak_fence";
52	export const IRON_BARS = "iron_bars";
53	export const POLISHED_BLACKSTONE_WALL = "polished_blackstone_wall";
54	export const LANTERN = "lantern";
55	export const IRON_CHAIN = "iron_chain";
56	export const POLISHED_ANDESITE = "polished_andesite";
57	export const SMOOTH_STONE_SLAB = "smooth_stone_slab";
58	export const GRASS_BLOCK = "grass_block";
59	export const PODZOL = "podzol";
60	export const BRICK_SLAB = "brick_slab";
61	export const FARMLAND = "farmland";
62	export const WATER = "water";
63	export const ROSE_BUSH = "rose_bush";
64	export const PEONY = "peony";
65	export const LILAC = "lilac";
66	export const AZALEA = "azalea";
67	export const FLOWERING_AZALEA = "flowering_azalea";
68	export const FERN = "fern";
69	export const LARGE_FERN = "large_fern";
70	export const OAK_LOG = "oak_log";
71	export const FLOWERING_AZALEA_LEAVES = "flowering_azalea_leaves";
72	export const OAK_LEAVES = "oak_leaves";
73	export const CARROTS = "carrots";
74	export const BEETROOTS = "beetroots";
75	export const POTATOES = "potatoes";
76	export const POTTED_FERN = "potted_fern";
