78	export const FLOWER_POT = "flower_pot";
79	export const SPRUCE_LOG = "spruce_log";
80	export const SPRUCE_FENCE = "spruce_fence";
81	export const SPRUCE_STAIRS = "spruce_stairs";
82	export const SPRUCE_SLAB = "spruce_slab";
83	export const SPRUCE_PRESSURE_PLATE = "spruce_pressure_plate";
84	export const SPRUCE_TRAPDOOR = "spruce_trapdoor";
85	export const CAMPFIRE = "campfire";
86	export const BOOKSHELF = "bookshelf";
87	export const SMOKER = "smoker";
88	export const BARREL = "barrel";
89	export const CAULDRON = "cauldron";
90	export const WATER_CAULDRON = "water_cauldron";
91	export const IRON_TRAPDOOR = "iron_trapdoor";
92	export const CRAFTING_TABLE = "crafting_table";
93	export const WHITE_BED = "white_bed";
94	export const RED_BED = "red_bed";
95	export const WHITE_CARPET = "white_carpet";
96	export const RED_CARPET = "red_carpet";
97	export const CYAN_CARPET = "cyan_carpet";
98	export const WHITE_WOOL = "white_wool";
99	export const LIGHTNING_ROD = "lightning_rod";
100	export const END_ROD = "end_rod";
101	export const OAK_PLANKS = "oak_planks";
102	
103	// ---- site (plan.md SITE and LEVELS). Boxes are inclusive [x0, y0, z0, x1, y1, z1]. Front = north (z0 = sidewalk). --
104	export const LOT = [0, 0, 0, 15, 20, 49];
105	export const SIDEWALK = [0, 0, 0, 15, 0, 1];
106	export const DRIVE = [1, 0, 2, 5, 0, 6];
107	export const FRONT_GARDEN = [7, 0, 3, 9, 0, 6];
108	export const FRONT_STAIR = [10, 0, 2, 14, 5, 6];
109	export const HOUSE = [1, 0, 7, 14, 16, 30];
110	export const BAY = [1, 3, 4, 6, 17, 6];
111	export const PORCH = [11, 4, 6, 13, 8, 9];
112	export const FALSE_FRONT = [1, 17, 7, 14, 20, 7];
113	export const LIGHTWELL = [1, 5, 19, 2, 20, 23];
114	export const ROOF = [0, 17, 7, 15, 20, 31];
115	export const DECK = [2, 0, 31, 13, 5, 38];
116	export const BACK_GARDEN = [1, 0, 31, 14, 2, 48];
117	export const FRONT_FACE_Z = 7;
118	export const BACK_FACE_Z = 30;
119	export const PARTY_WEST_X = 1;
120	export const PARTY_EAST_X = 14;
121	export const GROUND_Y = 0;
122	export const FLOOR_MAIN_Y = 4;
123	export const FLOOR_2ND_Y = 8;
124	export const FLOOR_TOP_Y = 12;
125	export const PLATE_Y = 16;
126	export const ROOF_Y = 17;
127	export const PEDIMENT_Y = 20;
128	export const WINDOW_YB = { main: 5, second: 9, top: 13 };
129	export const CARRIAGE_OPENING = [2, 1, 7, 5, 3, 7];
130	export const ENTRY_DOOR = { x: 12, y: 5, z: 10 };
131	export const FRONT_STEPS = { x0: 11, x1: 13, z0: 2, y0: 1, n: 4 };
132	export const RAIL_X = [10, 14];
133	export const RAIL_Z = [3, 6];
134	export const PORCH_COLUMNS = [[10, 7], [14, 7]];
135	export const HALL_LAMPS = [[12, 7, 14], [12, 7, 22], [12, 11, 22]];
136	export const CITRUS_TREE = { x: 4, z: 44 };
137	export const VEG_BED = [10, 0, 42, 13, 0, 46];
138	export const VEG_WATER = [[11, 0, 44], [12, 0, 44]];
139	export const VEG_CROPS = [
140	  { block: CARROTS, age: 7, box: [10, 42, 13, 43] },
141	  { block: BEETROOTS, age: 3, box: [10, 45, 13, 46] },
142	  { block: POTATOES, age: 7, box: [10, 44, 10, 44] },
143	  { block: POTATOES, age: 7, box: [13, 44, 13, 44] },
144	];
145	export const BENCH = { x0: 6, x1: 8, z: 48 };
146	export const LAMP_POST = { x: 9, z: 46 };
147	
148	const DOUBLE_PLANTS = new Set([ROSE_BUSH, PEONY, LILAC, LARGE_FERN]);
149	
150	// ---- internals ------------------------------------------------------------------------------------------------------
151	const isAir = (g, x, y, z) => ["minecraft:air", "minecraft:cave_air"].includes(g.blockAt(x, y, z));
152	// Add into air only. Returns false (and writes nothing) when another element already owns the cell.
153	function put(g, x, y, z, block, state) {
154	  if (!isAir(g, x, y, z)) return false;
155	  g.set(x, y, z, block, state);
156	  return true;
157	}
158	// A cell list or box list: [x, y, z] is one cell, [x0, y0, z0, x1, y1, z1] an inclusive box.
159	const inBoxes = (list, x, y, z) => list.some((c) => (c.length === 3
160	  ? c[0] === x && c[1] === y && c[2] === z
161	  : x >= Math.min(c[0], c[3]) && x <= Math.max(c[0], c[3]) && y >= Math.min(c[1], c[4]) && y <= Math.max(c[1], c[4])
162	    && z >= Math.min(c[2], c[5]) && z <= Math.max(c[2], c[5])));
163	const isZWall = (out) => out === "north" || out === "south";
164	// Wall geometry. `along` is x on a north/south wall and z on an east/west wall; `plane` is the wall's own coordinate
165	// (z on a north/south wall, x on an east/west wall). `out` is the outward direction of the wall.
166	const onWall = (along, y, plane, out) => (isZWall(out) ? [along, y, plane] : [plane, y, along]);
167	const oneOut = (along, y, plane, out) => {
168	  const [dx, , dz] = DIRS[out];
169	  return isZWall(out) ? [along, y, plane + dz] : [plane + dx, y, along];
170	};
171	// Facing of a stair that climbs toward +along and toward -along: [toward +along, toward -along].
172	const alongFacings = (out) => (isZWall(out) ? ["east", "west"] : ["south", "north"]);
173	
174	// ---- shell -----------------------------------------------------------------------------------------------------------
175	// Front and back courses: y0..3 base, y4 belt, siding, fish-scale bands y8/y12, frieze y16, parapet y17..18.
176	// Party and lightwell walls are cyan base then birch; inner partitions are birch.
177	export function wallCell(g, x, y, z, kind) {
178	  let block = null;
179	  if (kind === "front" || kind === "back") {
180	    if (y <= 3) block = CYAN_TERRACOTTA;
181	    else if (y === 4) block = SMOOTH_QUARTZ;
182	    else if (y === 8 || y === 12 || y === 18) block = y === 18 && [1, 5, 10, 14].includes(x) ? SMOOTH_QUARTZ : BAMBOO_MOSAIC;
183	    else if (y === 16) block = CRIMSON_PLANKS;
184	    else if (y === 5 || y === 6 || y === 7 || y === 9 || y === 10 || y === 11 || y === 13 || y === 14 || y === 15 || y === 17) block = WARPED_PLANKS;
185	  } else if (kind === "party") {
186	    if (y <= 3) block = CYAN_TERRACOTTA;
187	    else if (y <= 16) block = BIRCH_PLANKS;
188	  } else if (kind === "inner") {
189	    block = BIRCH_PLANKS;
190	  } else {
191	    throw new Error(`wallCell: unknown kind ${kind}`);
192	  }
193	  if (block) g.set(x, y, z, block);
194	}
195	
196	// A straight or rectangular run of wallCell, minus open cells (left unset).
197	export function wallLine(g, x0, z0, x1, z1, y0, y1, kind, { open = [] } = {}) {
198	  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++)
199	    for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++)
200	      for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++)
201	        if (!inBoxes(open, x, y, z)) wallCell(g, x, y, z, kind);
202	}
203	
204	// Floor fill at height y. block is an id or [id, state]; holes are cells or boxes left unset.
205	export function slab(g, y, x0, z0, x1, z1, block, { holes = [] } = {}) {
206	  const [id, state] = Array.isArray(block) ? block : [block, undefined];
207	  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++)
208	    for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++)
209	      if (!inBoxes(holes, x, y, z)) g.set(x, y, z, id, state);
210	}
211	
212	// ---- front facade -----------------------------------------------------------------------------------------------------
213	// 1-wide, 3-tall glass in a wall (x on a north/south wall, z on an east/west wall) with a sill 1 out; hood 1 out above.
214	export function tallWindow(g, along, yb, plane, out, { hood = false } = {}) {
215	  const [towardPlus, towardMinus] = alongFacings(out);
216	  for (let k = 0; k < 3; k++) put(g, ...onWall(along, yb + k, plane, out), ...B.pane());
217	  put(g, ...oneOut(along, yb - 1, plane, out), ...B.slab("smooth_quartz", "top"));
218	  if (hood) {
219	    put(g, ...oneOut(along - 1, yb + 3, plane, out), ...B.stairs("smooth_quartz", towardPlus, "bottom"));
220	    put(g, ...oneOut(along, yb + 3, plane, out), CHISELED_QUARTZ_BLOCK);
221	    put(g, ...oneOut(along + 1, yb + 3, plane, out), ...B.stairs("smooth_quartz", towardMinus, "bottom"));
222	  }
223	}
224	
225	// Bay front: 2-wide glass on z5 at x3..4, sill on z4, pediment hood on z4 from x2 to x5.
226	export function pairedWindow(g, yb) {
227	  for (let y = yb; y <= yb + 2; y++) for (const x of [3, 4]) put(g, x, y, 5, ...B.pane());
228	  for (const x of [3, 4]) put(g, x, yb - 1, 4, ...B.slab("smooth_quartz", "top"));
229	  put(g, 2, yb + 3, 4, ...B.stairs("smooth_quartz", "east", "bottom"));
230	  for (const x of [3, 4]) put(g, x, yb + 3, 4, CHISELED_QUARTZ_BLOCK);
231	  put(g, 5, yb + 3, 4, ...B.stairs("smooth_quartz", "west", "bottom"));
232	}
233	
234	// Angled-bay diagonal face at x 1 or 6: glass on z6, sill and hood on z5.
235	export function diagWindow(g, x, yb) {
236	  for (let y = yb; y <= yb + 2; y++) put(g, x, y, 6, ...B.pane());
237	  put(g, x, yb - 1, 5, ...B.slab("smooth_quartz", "top"));
238	  put(g, x, yb + 3, 5, ...B.slab("smooth_quartz", "bottom"));
239	}
240	
241	// Cornice pieces: a bracket and a crown lip toward the street, the corbel under the bay (y3).
242	export function bracket(g, x, y, z) {
243	  put(g, x, y, z, ...B.stairs("quartz", "south", "top"));
244	}
245	export function crown(g, x, y, z) {
246	  put(g, x, y, z, ...B.stairs("smooth_quartz", "south", "top"));
247	}
248	export function corbel(g, x, z) {
249	  put(g, x, 3, z, ...B.stairs("smooth_quartz", "south", "top"));
250	}
251	
252	// Porch column: quartz base, pillar, chiseled capital.
253	export function column(g, x, z) {
254	  put(g, x, 5, z, QUARTZ_BLOCK);
255	  put(g, x, 6, z, ...B.pillar("quartz_pillar", "y"));
256	  put(g, x, 7, z, CHISELED_QUARTZ_BLOCK);
257	}
258	
259	// E5 exactly: the front door at (12, 5..6, 10) with glass sidelights and a transom.
260	export function entryDoor(g) {
261	  const { x, y, z } = ENTRY_DOOR;
262	  door(g, x, y, z, "north", "left", "crimson");
263	  for (const sx of [x - 1, x + 1]) for (const sy of [y, y + 1]) put(g, sx, sy, z, ...B.pane());
264	  for (const tx of [x - 1, x, x + 1]) put(g, tx, y + 2, z, ...B.pane());
265	}
266	
267	// E2 exactly: two pairs of crimson carriage doors at y1..2 on z7, glass transom at y3.
268	export function carriageDoor(g) {
269	  const [x0, y0, z, x1, y1] = CARRIAGE_OPENING;
270	  [[2, "left"], [3, "right"], [4, "left"], [5, "right"]].forEach(([x, hinge]) => door(g, x, y0, z, "north", hinge, "crimson"));
271	  for (let x = x0; x <= x1; x++) put(g, x, y1, z, ...B.pane());
272	}
273	
274	// Two-cell door: lower at y, upper at y+1. wood is a palette wood (birch, crimson).
275	export function door(g, x, y, z, facing, hinge, wood = "birch") {
276	  put(g, x, y, z, ...B.door(wood, facing, "lower", hinge));
277	  put(g, x, y + 1, z, ...B.door(wood, facing, "upper", hinge));
278	}
279	
280	// ---- stairs, rails, lamps ---------------------------------------------------------------------------------------------
281	// n stairs, each one up and one along `facing`. block is a stairs id (e.g. quartz_stairs).
282	export function stairFlight(g, x, z0, y0, n, facing, block) {
283	  const [dx, , dz] = DIRS[facing];
284	  for (let i = 0; i < n; i++) put(g, x + i * dx, y0 + i, z0 + i * dz, ...B.stairs(block.replace(/_stairs$/, ""), facing, "bottom"));
285	}
286	
287	// Stringer from the base up to the tread height beside each cell of the front stair, then a birch fence rail above it.
288	export function stairRail(g, x, z0, z1) {
289	  const { z0: sz0, y0, n } = FRONT_STEPS;
290	  for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
291	    const tread = Math.min(Math.max(z - sz0 + y0, y0), y0 + n - 1);
292	    for (let y = 1; y <= tread; y++) put(g, x, y, z, CYAN_TERRACOTTA);
293	    put(g, x, tread + 1, z, ...B.fence("birch"));
294	  }
295	}
296	
297	// Quartz newel with a standing lantern on top.
298	export function newelLamp(g, x, z) {
299	  put(g, x, 1, z, QUARTZ_PILLAR, { axis: "y" });
300	  put(g, x, 2, z, QUARTZ_PILLAR, { axis: "y" });
301	  put(g, x, 3, z, ...B.lantern(false));
302	}
303	
304	// Iron bar runs at y1. Each run is an ordered list of [x, z]; its two end cells are polished blackstone wall posts y1..2.
305	export function ironFence(g, runs) {
306	  for (const run of runs) {
307	    run.forEach(([x, z], i) => {
308	      if (i === 0 || i === run.length - 1) {
309	        put(g, x, 1, z, POLISHED_BLACKSTONE_WALL, {});
310	        put(g, x, 2, z, POLISHED_BLACKSTONE_WALL, {});
311	      } else {
312	        put(g, x, 1, z, IRON_BARS, {});
313	      }
314	    });
315	  }
316	}
317	
318	// ---- garden, ground, trees -------------------------------------------------------------------------------------------
319	// Podzol bed over box (ground, written directly); plants [x, z, id] at y1. Double plants fill y1 and y2.
320	export function gardenBed(g, box, plants) {
321	  const [x0, y0, z0, x1, , z1] = box;
322	  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++)
323	    for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) g.set(x, y0, z, PODZOL);
324	  for (const [x, z, id] of plants) {
325	    if (DOUBLE_PLANTS.has(id)) {
326	      put(g, x, 1, z, id, { half: "lower" });
327	      put(g, x, 2, z, id, { half: "upper" });
328	    } else {
329	      put(g, x, 1, z, id, {});
330	    }
331	  }
332	}
333	
334	// Chain at y and a hanging lantern at y-1 under a ceiling at y+1 (drop 2). drop 1: just the lantern at y.
335	export function hangLamp(g, x, y, z, { drop = 2 } = {}) {
336	  if (isAir(g, x, y + 1, z)) throw new Error(`hangLamp at ${x},${y},${z}: no ceiling directly above`);
337	  if (drop === 2) {
338	    put(g, x, y, z, ...B.chain("y"));
339	    put(g, x, y - 1, z, ...B.lantern(true));
340	  } else {
341	    put(g, x, y, z, ...B.lantern(true));
342	  }
343	}
344	
345	// Dark oak post y1..2 with a standing lantern at y3.
346	export function lampPost(g, x, z) {
347	  put(g, x, 1, z, DARK_OAK_FENCE, {});
348	  put(g, x, 2, z, DARK_OAK_FENCE, {});
349	  put(g, x, 3, z, ...B.lantern(false));
350	}
351	
352	// Trunk x,z at y1..3 on a 3x3 podzol base; persistent leaves: flowering azalea (ring at y3, plus y4 and y5), oak corners at y4.
353	export function citrusTree(g, x, z) {
354	  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) g.set(x + dx, 0, z + dz, PODZOL);
355	  for (let y = 1; y <= 3; y++) put(g, x, y, z, ...B.log("oak", "y"));
356	  const leaf = (lx, ly, lz, id) => put(g, lx, ly, lz, id, { persistent: "true" });
357	  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) if (dx || dz) leaf(x + dx, 3, z + dz, FLOWERING_AZALEA_LEAVES);
358	  for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) {
359	    const corner = Math.abs(dx) === 1 && Math.abs(dz) === 1;
360	    leaf(x + dx, 4, z + dz, corner ? OAK_LEAVES : FLOWERING_AZALEA_LEAVES);
361	  }
362	  for (const [dx, dz] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) leaf(x + dx, 5, z + dz, FLOWERING_AZALEA_LEAVES);
363	}
364	
365	// Farmland bed over box at y0 with water cells, crops at y1 (VEG_CROPS, E29), and closed spruce trapdoor edging at y1 on
366	// the orthogonal cells just outside the bed (skip: cells or boxes left bare, e.g. the path).
367	export function vegBed(g, box, water, { skip = [], crops = VEG_CROPS } = {}) {
368	  const [x0, y0, z0, x1, , z1] = box;
369	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
370	    if (inBoxes(water, x, y0, z)) g.set(x, y0, z, WATER);
371	    else g.set(x, y0, z, FARMLAND, { moisture: "7" });
372	  }
373	  for (const c of crops) {
374	    const [cx0, cz0, cx1, cz1] = c.box;
375	    for (let x = cx0; x <= cx1; x++) for (let z = cz0; z <= cz1; z++) put(g, x, 1, z, c.block, { age: String(c.age) });
376	  }
377	  const rim = [];
378	  for (let x = x0; x <= x1; x++) rim.push([x, z0 - 1], [x, z1 + 1]);
379	  for (let z = z0; z <= z1; z++) rim.push([x0 - 1, z], [x1 + 1, z]);
380	  for (const [x, z] of rim) if (!inBoxes(skip, x, 1, z)) put(g, x, 1, z, ...B.trapdoor("spruce", "north", "bottom", false));
381	}
382	
383	// ---- deck and back garden -------------------------------------------------------------------------------------------
384	// Spruce fence rail at y5 on each [x, z] cell.
385	export function deckRail(g, cells) {
386	  for (const [x, z] of cells) put(g, x, 5, z, ...B.fence("spruce"));
387	}
388	
389	// Table: fence y5 + pressure plate y6; chairs on the north and south sides, each facing away from the table.
390	export function deckTable(g, x, z) {
391	  put(g, x, 5, z, ...B.fence("spruce"));
392	  put(g, x, 6, z, SPRUCE_PRESSURE_PLATE, {});
393	  put(g, x, 5, z - 1, ...B.stairs("spruce", "north", "bottom"));
394	  put(g, x, 5, z + 1, ...B.stairs("spruce", "south", "bottom"));
395	}
396	
397	// Seat x0..x1 at y1 on z, facing south (the house); open trapdoor arms one cell beyond each end.
398	export function bench(g, x0, x1, z) {
399	  for (let x = x0; x <= x1; x++) put(g, x, 1, z, ...B.stairs("spruce", "south", "bottom"));
400	  put(g, x0 - 1, 1, z, ...B.trapdoor("spruce", "south", "bottom", true));
401	  put(g, x1 + 1, 1, z, ...B.trapdoor("spruce", "south", "bottom", true));
402	}
403

